export function uberBlGeneralBuild(root){ if(root) _root=root; aBuildMargins(); aBuildExpenses(); }

// ═══ BL-SEG Bottom Line ▸ Segments (playbook §13 BL-SEG) — copied from googl-bl.js's segment section ═══
// Stacked, no picker: Profit by segment → Revenue vs profit → The segment bridge → Segment deep dives → footer.
// Uber discloses, by segment: revenue, Gross Bookings (release KPI), segment profit, and a two-way cost split
// (Platform Participant direct transaction costs · other). Corporate G&A and Platform R&D is its own unallocated line,
// so the three segments plus it add up to Adjusted EBITDA / Non-GAAP operating income. Two segment measures, never
// spliced: Segment Adjusted EBITDA (through 4Q25) and Segment Operating Income (recast from 1Q24; the measure since 1Q26).
function sPane(){ return R().querySelector('.dd-pane[data-dd="bottomline"] .ovt-subpane[data-ovst="segments"]')||R().querySelector('.ovt-subpane[data-ovst="segments"]'); }
var SEG_DEF=[{k:'mob',lab:'Mobility',c:SUMMIT_CAT[0],rk:'mobrev',gk:'mobgb',bbg:'mobility'},
             {k:'del',lab:'Delivery',c:SUMMIT_CAT[1],rk:'delrev',gk:'delgb',bbg:'delivery'},
             {k:'fr',lab:'Freight',c:SUMMIT_CAT[2],rk:'frrev',gk:'frgb',bbg:'freight'},
             {k:'corp',lab:'Corporate G&A and Platform R&D',c:MUTE,rk:null,gk:null,bbg:'seg355661',loss:true}];
var SEG_CONS={k:'cons',lab:'Consolidated',c:INK,rk:'rev',gk:'gb'};
var SEG_SPLIT=SEG_DEF.filter(function(s){ return s.k!=='corp'; });
function sSeg(k){ return k==='cons'?SEG_CONS:SEG_DEF.filter(function(s){ return s.k===k; })[0]||SEG_DEF[0]; }
function sB(v){ if(v==null) return '—'; var a=Math.abs(v); return (v<0?'−':'')+'$'+(a<1000?Math.round(a)+'M':(a/1000).toFixed(1)+'B'); }
function sPct(v){ return v==null?'—':(v<0?'−':'')+Math.abs(v).toFixed(1)+'%'; }
function sLastIdx(a){ var j=-1; (a||[]).forEach(function(v,i){ if(v!=null) j=i; }); return j; }
function sSeries(k){ return k==='cons'?null:(uberBBG.seg[sSeg(k).bbg]||{}); }
// Segment profit, reported, by measure. soi = Segment Operating Income; ebitda = Segment Adjusted EBITDA.
function soiQ(k,p){ for(var i=0;i<UBER_SEG_SOI_Q.length;i++){ var r=UBER_SEG_SOI_Q[i]; if(r.p===p) return k==='cons'?ngoiQ(p):(k==='corp'?r.corp:r[k].oi); } return null; }
function soiY(k,y){ var t=0; for(var q=1;q<=4;q++){ var v=soiQ(k,q+'Q'+String(y).slice(2)); if(v==null) return null; t+=v; } return t; }
function ebQ(k,p){ if(k==='cons') return rq('ebitda','act',p); for(var i=0;i<UBER_SEG_EBITDA_Q.length;i++) if(UBER_SEG_EBITDA_Q[i].p===p) return UBER_SEG_EBITDA_Q[i][k]; return null; }
function ebY(k,y){ if(k==='cons') return ry('ebitda','act',y); var r=UBER_SEG_EBITDA_Y[y]; if(!r) return null; return k==='corp'?r.corp:r[k].oi; }
// Annual axis for segments: 2023 (first Adjusted EBITDA year in the 10-K table) → the BBG forward years.
var S_YA=[2023,2024,2025].filter(function(y){ return y<=A_YA[A_LA]; }), S_LA=S_YA.length-1;
var S_YRS=S_YA.concat(A_YF.filter(function(y){ return y>S_YA[S_LA]; }));
var S_LAB=S_YRS.map(function(y,i){ return fyLab(y)+(i>S_LA?'E':''); });
// Quarterly axis: the Results dataset's quarters (3Q22 … 1Q27).
var S_QP=RQ.mobrev.periods.slice(), S_QLA=aLastActIdx(RQ.mobrev.act);
function denY(s, gb, src, y){   // segment (or consolidated) revenue / Gross Bookings for a year, by source
  if(s.k==='corp') return null;
  if(src==='act') return ry(gb?s.gk:s.rk,'act',y);
  if(src==='sum'){ var o=s.k==='cons'?UBER_SUMMIT:UBER_SUMMIT.seg[s.k]; return aSummitAt(o&&(gb?o.gb:o.rev),y); }
  var S=s.k==='cons'?uberBBG.is:sSeries(s.k); return aFyVal(S&&(gb?S.grossBookings||S.gb:S.rev),y); }
function denQ(s, gb, src, p){ if(s.k==='corp') return null; return rq(gb?s.gk:s.rk, src==='sum'?'summit':(src==='con'?'cons':'act'), p); }

// ── 1 · Profit by segment — Actual vs Summit vs Consensus ──
function sProfitBody(){
  return aStdScaffold({ id:'ub-segfc', title:'Profit by segment — Actual vs Summit vs Consensus', height:340,
    modes:[{cls:'seg',label:'Segment',opts:SEG_DEF.concat([SEG_CONS]).map(function(s,i){ return {v:s.k,label:s.lab,on:i===0}; })},
           {cls:'meas',label:'Measure',opts:[{v:'soi',label:'Segment operating income (from 1Q24)',on:true},{v:'ebitda',label:'Segment Adjusted EBITDA (through 4Q25)'}]},
           {cls:'gran',label:'Period',opts:[{v:'y',label:'Annual',on:true},{v:'q',label:'Quarterly'}]},
           {cls:'base',label:'Margin on',opts:[{v:'gb',label:'Gross Bookings',on:true},{v:'rev',label:'Revenue'}]}],
    presets:[['all','All'],['rep','Reported'],['fwd','Forward'],['l5','Last 5']] });
}
function sBuildProfit(){
  aStdRender('ub-segfc', function(st){
    var s=sSeg(st.modes.seg||'mob'), meas=st.modes.meas||'soi', gran=st.modes.gran||'y', gb=(st.modes.base||'gb')==='gb', loss=!!s.loss, cons=s.k==='cons';
    var lab=cons?(meas==='soi'?'Non-GAAP op. income':'Adj. EBITDA'):(meas==='soi'?'Segment op. income':'Segment Adj. EBITDA');
    var labels, la, act, sum, con, dA, dS, dC, S=sSeries(s.k);
    if(gran==='q'){
      var per=S_QP.slice(), first=meas==='soi'?'1Q24':'1Q23';
      per=per.slice(Math.max(0,per.indexOf(first)));
      act=per.map(function(p){ return meas==='soi'?soiQ(s.k,p):ebQ(s.k,p); }); la=aLastActIdx(act);
      if(meas==='soi'){ sum=per.map(function(p,i){ return (cons&&i>la)?rq('opinc','summit',p):null; });
        con=per.map(function(p,i){ if(i<=la) return null; return cons?rq('opinc','cons',p):bbgQF(S&&S.oi,p); }); }
      else if(cons){ sum=per.map(function(p,i){ return i>la?rq('ebitda','summit',p):null; }); con=per.map(function(p,i){ return i>la?rq('ebitda','cons',p):null; }); }
      else { per=per.slice(0,la+1); act=act.slice(0,la+1); sum=null; con=null; }
      labels=per;
      dA=per.map(function(p){ return denQ(s,gb,'act',p); }); dS=per.map(function(p){ return denQ(s,gb,'sum',p); }); dC=per.map(function(p){ return denQ(s,gb,'con',p); });
      labels=labels.map(function(p,i){ return i>la?p+'E':p; });
    } else {
      var yrs=S_YRS.slice(); la=S_LA;
      act=yrs.map(function(y,i){ return i>la?null:(meas==='soi'?(cons?ngoiY(y):soiY(s.k,y)):ebY(s.k,y)); });
      if(meas==='soi'){ sum=yrs.map(function(y){ return aSummitAt(cons?UBER_SUMMIT.ngoi:UBER_SUMMIT.seg[s.k].soi,y); });
        con=yrs.map(function(y,i){ return i>la?aFyVal(cons?uberBBG.is.ngoi:(S&&S.oi),y):null; }); }
      else if(cons){ sum=yrs.map(function(y){ return aSummitAt(UBER_SUMMIT.ebitda,y); }); con=yrs.map(function(y,i){ return i>la?aIsVal('ebitda',y):null; }); }
      else { yrs=yrs.slice(0,la+1); act=act.slice(0,la+1); sum=null; con=null; }
      labels=yrs.map(function(y,i){ return fyLab(y)+(i>la?'E':''); });
      dA=yrs.map(function(y){ return denY(s,gb,'act',y); }); dS=yrs.map(function(y){ return denY(s,gb,'sum',y); }); dC=yrs.map(function(y){ return denY(s,gb,'con',y); });
    }
    function amt(a){ return labels.map(function(_,i){ return a&&a[i]!=null?Math.round(a[i]/100)/10:null; }); }
    function marg(a,r){ return labels.map(function(_,i){ return (a&&a[i]!=null&&r&&r[i])?Math.round(a[i]/r[i]*1000)/10:null; }); }
    var series=[
      {k:'act$',grp:'act',src:'Actual',label:lab+' — Actual',color:ASTD_ACT,type:'bar',data:amt(act)},
      {k:'sum$',grp:'sum',src:SUM_SRC,label:lab+' — Summit',color:ASTD_SUMMIT,type:'bar',data:amt(sum)},
      {k:'con$',grp:'con',src:'Consensus',label:lab+' — Consensus',color:ASTD_CONS,type:'bar',data:amt(con)}];
    if(!loss) series.push(
      {k:'actM',grp:'act',src:'Actual',label:'Margin — Actual',color:ASTD_ACT,type:'line',yAxisID:'y2',data:marg(act,dA)},
      {k:'sumM',grp:'sum',src:SUM_SRC,label:'Margin — Summit',color:ASTD_SUMMIT,type:'line',yAxisID:'y2',data:marg(sum,dS)},
      {k:'conM',grp:'con',src:'Consensus',label:'Margin — Consensus',color:ASTD_CONS,type:'line',yAxisID:'y2',dash:true,data:marg(con,dC)});
    series=series.filter(function(x){ return x.data.some(function(v){ return v!=null; }); });
    var end=Math.max.apply(null, series.map(function(x){ return sLastIdx(x.data); }));
    if(end>=0 && end<labels.length-1){ labels=labels.slice(0,end+1); series.forEach(function(x){ x.data=x.data.slice(0,end+1); }); }
    var first=Math.min.apply(null, series.map(function(x){ var j=x.data.findIndex(function(v){ return v!=null; }); return j<0?labels.length:j; }));
    if(first>0 && first<labels.length){ labels=labels.slice(first); series.forEach(function(x){ x.data=x.data.slice(first); }); la-=first; }
    var notes=[];
    if(meas==='soi') notes.push(cons?'Non-GAAP operating income = the three segments plus Corporate G&amp;A and Platform R&amp;D.':'Segment Operating Income — Uber’s segment measure since 1Q26, recast back to 1Q24 (Form 8-K, Jan 12 2026). It is after stock-based compensation and depreciation, so it sits below the old Segment Adjusted EBITDA; the two are never joined in one series.');
    else notes.push(cons?'Consolidated Adjusted EBITDA — Uber still reports and guides it.':'Segment Adjusted EBITDA — Uber’s segment measure through 4Q25 (10-K FY2025 Note 13; 10-Q segment notes). Retired after 4Q25, so it has no forecast here: brokers still carry one in Bloomberg, but no print will report it.');
    if(!cons) notes.push(gran==='q'?'Summit is not drawn quarterly: the model projects segment operating income by year only.':'Summit = the model’s segment operating income (frozen, snapshot '+esc(UBER_SUMMIT.snapshot)+'); consensus = Bloomberg’s segment operating income.');
    if(s.k==='mob'&&!gb) notes.push('From 1Q26 the UK business-model change lowers Mobility revenue by about $1B a quarter with no effect on profit, so the margin on revenue jumps; the margin on Gross Bookings reads through it.');
    if(s.k==='corp') notes.push('“'+esc(UBER_SEG_TXT.corp)+'” No revenue of its own, so no margin.');
    if(s.k==='fr') notes.push('Freight is reported gross, so revenue and Gross Bookings are close.');
    notes.push(gb?'Margin on Gross Bookings, Uber’s own convention.':'Margin on revenue.');
    var out={ labels:labels, lastAct:la, type:'bar', stacked:false, series:series, note:notes.join(' '),
      yFmt:function(x){ return (x<0?'−$':'$')+(x==null?'':Math.abs(x).toFixed(1))+'B'; }, y2Fmt:function(x){ return x+'%'; } };
    if(loss){ out.legCap='Bars = loss, $B'; out.hideModes=['base']; } else out.paired=true;
    return out;
  });
}

// ── 2 · Revenue vs profit — common size by segment ──
function sMixBody(){
  return aStdScaffold({ id:'ub-segmix', title:'Gross Bookings, revenue and profit — common size by segment', height:340,
    metricSel:[{v:'gb',label:'Gross Bookings',on:true,group:'Volume'},{v:'rev',label:'Revenue',group:'Revenue'},{v:'soi',label:'Segment operating income',group:'Profit'}],
    modes:[{cls:'basis',label:'Basis',opts:[{v:'cons',label:'Actual + Consensus',on:true},{v:'summit',label:'Actual + Summit'}]},
           {cls:'show',label:'Show',opts:[{v:'amt',label:'$B',on:true},{v:'share',label:'Share'},{v:'growth',label:'Growth'}]},
           {cls:'layout',label:'Layout',opts:[{v:'stack',label:'Stacked',on:true},{v:'side',label:'Side by side'}]},
           {cls:'gran',label:'Period',opts:[{v:'y',label:'Annual',on:true},{v:'q',label:'Quarterly'}]},
           {cls:'cmp',label:'Compare',opts:[{v:'yoy',label:'YoY',on:true},{v:'qoq',label:'QoQ'}]},
           {cls:'gin',label:'Growth in',opts:[{v:'pct',label:'%',on:true},{v:'add',label:'$ added'}]}],
    presets:[['all','All'],['rep','Reported'],['fwd','Forward']] });
}
function sBuildMix(){
  aStdRender('ub-segmix', function(st){
    var metric=st.sel||'gb', basis=st.modes.basis||'cons', show=st.modes.show||'amt', layout=st.modes.layout||'stack', gran=st.modes.gran||'y';
    var cmp=st.modes.cmp||'yoy', gin=st.modes.gin||'pct', notes=[];
    if(basis==='summit') gran='y';
    var labels, la;
    if(gran==='q'){ labels=S_QP.slice(); la=S_QLA; } else { labels=S_LAB.slice(); la=S_LA; }
    var defs=metric==='soi'?SEG_DEF:SEG_SPLIT;
    function raw(s){
      if(gran==='q') return S_QP.map(function(p,i){
        if(metric==='soi') return i<=la?soiQ(s.k,p):bbgQF((sSeries(s.k)||{}).oi,p);
        return rq(metric==='gb'?s.gk:s.rk, i<=la?'act':'cons', p); });
      return S_YRS.map(function(y,i){
        if(i<=la) return metric==='soi'?soiY(s.k,y):ry(metric==='gb'?s.gk:s.rk,'act',y);
        if(basis==='summit'){ var o=UBER_SUMMIT.seg[s.k]; return aSummitAt(o&&(metric==='soi'?o.soi:(metric==='gb'?o.gb:o.rev)),y); }
        var S=sSeries(s.k)||{}; return aFyVal(metric==='soi'?S.oi:(metric==='gb'?S.grossBookings:S.rev),y); }); }
    var step=gran==='q'?(cmp==='qoq'?1:4):1, addMode=(show==='growth'&&gin==='add');
    var rows=defs.map(function(s){ return { s:s, v:raw(s) }; });
    var totals=labels.map(function(_,i){ var t=0, any=false; rows.forEach(function(r){ if(r.v[i]!=null){ t+=r.v[i]; any=true; } }); return any?t:null; });
    function val(v, pv, tot){ if(v==null) return null;
      if(show==='share') return tot?Math.round(v/tot*1000)/10:null;
      if(show==='growth'){ if(pv==null) return null; if(addMode) return Math.round((v-pv)/100)/10; return !pv?null:Math.round((v-pv)/Math.abs(pv)*1000)/10; }
      return Math.round(v/100)/10; }
    var series=rows.map(function(r){ return { k:r.s.k, label:r.s.lab, color:r.s.c, type:'bar',
      data:labels.map(function(_,i){ return val(r.v[i], r.v[i-step], totals[i]); }) }; });
    if(metric==='soi'&&show==='amt') series.push({ k:'tot', label:'Non-GAAP operating income', color:INK, type:'line', stack:'tot',
      data:totals.map(function(v){ return v==null?null:Math.round(v/100)/10; }) });
    var first=Math.min.apply(null, series.map(function(x){ var j=x.data.findIndex(function(v){ return v!=null; }); return j<0?labels.length:j; }));
    var end=Math.max.apply(null, series.map(function(x){ return sLastIdx(x.data); }));
    if(end>=0 && end<labels.length-1){ labels=labels.slice(0,end+1); series.forEach(function(x){ x.data=x.data.slice(0,end+1); }); }
    if(first>0 && first<labels.length){ labels=labels.slice(first); series.forEach(function(x){ x.data=x.data.slice(first); }); la-=first; }
    labels=labels.map(function(l,i){ return (gran==='q'&&i>la)?l+'E':l; });
    if(metric==='soi'){ notes.push('Segment Operating Income, recast from 1Q24; Corporate G&amp;A and Platform R&amp;D sits below zero, and the line is Non-GAAP operating income (their sum).');
      if(show==='share') notes.push('Share = each line ÷ Non-GAAP operating income; the unallocated corporate line is negative, so the segments add up to more than 100%.'); }
    if(metric==='rev') notes.push('Revenue depends on where Uber is the principal or the agent: from 1Q26 the UK change takes about $1B a quarter out of Mobility revenue. Gross Bookings read through it.');
    if(metric==='gb') notes.push('Gross Bookings — the total value of trips, orders and shipments (a release KPI, not revenue). Freight is reported gross, so its Gross Bookings and revenue are close.');
    if(basis==='summit') notes.push('Actual through '+esc(labels[la]||'')+', then the Summit model (frozen, snapshot '+esc(UBER_SUMMIT.snapshot)+') — annual only.');
    else notes.push('Forward = Bloomberg consensus by segment (as of '+esc(uberBBG.asOf)+').');
    var stacked=show==='share'||(show==='amt'&&layout==='stack')||(addMode&&layout==='stack');
    var yFmt=(show==='amt'||addMode)?function(x){ return (x<0?'−$':'$')+(x==null?'':Math.abs(x).toFixed(1))+'B'; }:function(x){ return x+'%'; };
    var hide=[]; if(!(show==='growth'&&gran==='q')) hide.push('cmp'); if(show!=='growth') hide.push('gin'); if(show==='share') hide.push('layout');
    if(basis==='summit') hide.push('gran');
    return { labels:labels, lastAct:la, yFmt:yFmt, type:'bar', stacked:stacked, yMax:(show==='share'&&metric!=='soi')?100:undefined, series:series, hideModes:hide, note:notes.join(' ') };
  });
}

// ── 3 · The segment bridge — By segment (Δ segment operating income, reported and consensus years) | By cost ──
// By cost uses the two-way split the filings give: Segment Adjusted EBITDA basis for the years (10-K Note 13), Segment
// Operating Income basis for the quarters (each against the same quarter a year earlier, where both carry the split).
var SBR_QS=UBER_SEG_SOI_Q.filter(function(r,i){ if(i<4||r.mob.pp==null) return false; var b=UBER_SEG_SOI_Q[i-4]; return b&&b.mob.pp!=null; });
var SEG_YRS=Object.keys(UBER_SEG_EBITDA_Y).map(Number).sort();
var SBR_YA=S_YRS.filter(function(y){ return y>=2024; });   // Segment Operating Income starts in 2024
function sOiY(y, s){ var i=S_YRS.indexOf(y); if(i<0) return null; return i<=S_LA?soiY(s.k,y):aFyVal((sSeries(s.k)||{}).oi,y); }
function sBridgeBody(){
  function yB(cls, ys, sel){ return ys.map(function(y){ return '<button type="button" data-'+cls+'="'+y+'"'+(y===sel?' class="active"':'')+'>'+fyLab(y)+(y>S_YA[S_LA]?'E':'')+'</button>'; }).join(''); }
  var nC=SEG_YRS.length, qL=SBR_QS[SBR_QS.length-1].p, ra=SBR_YA.filter(function(y){ return y<=S_YA[S_LA]; });
  return '<div class="ov-sec"><div class="ov-sec-h">The segment bridge — what moved segment profit</div>'+
    '<div class="mch-ctl"><span class="acx-tog sbr-mode"><button type="button" data-sbrm="seg" class="active">By segment</button><button type="button" data-sbrm="cost">By cost — revenue, platform-participant costs, other</button></span><span></span></div>'+
    '<div class="sbr-ctl-seg mch-ctl me-bl-ctl"><span></span><span class="me-bl-pills">'+
      '<span class="me-bl-lbl">From</span><span class="acx-tog sbr-from">'+yB('sbrf',SBR_YA,ra[0])+'</span>'+
      '<span class="me-bl-lbl">to</span><span class="acx-tog sbr-to">'+yB('sbrt',SBR_YA,ra[ra.length-1])+'</span></span></div>'+
    '<div class="sbr-ctl-cost mch-ctl me-bl-ctl" hidden>'+
      '<span class="acx-tog sbr-seg">'+SEG_SPLIT.map(function(s,i){ return '<button type="button" data-sbrs="'+s.k+'"'+(i===0?' class="active"':'')+'>'+esc(s.lab)+'</button>'; }).join('')+'</span>'+
      '<span class="me-bl-pills"><span class="acx-tog sbr-gran"><button type="button" data-sbrg="y" class="active">Annual</button><button type="button" data-sbrg="q">Quarterly</button></span>'+
        '<span class="sbr-cy"><span class="me-bl-lbl">From</span><span class="acx-tog sbr-cfrom">'+yB('sbrcf',SEG_YRS,SEG_YRS[nC-2])+'</span>'+
        '<span class="me-bl-lbl">to</span><span class="acx-tog sbr-cto">'+yB('sbrct',SEG_YRS,SEG_YRS[nC-1])+'</span></span>'+
        '<span class="acx-tog sbr-cq" hidden>'+SBR_QS.map(function(r){ return '<button type="button" data-sbrq="'+r.p+'"'+(r.p===qL?' class="active"':'')+'>'+r.p+'</button>'; }).join('')+'</span>'+
      '</span></div>'+
    '<div class="me-bl-h340"><canvas id="ubSegBr"></canvas></div>'+
    '<div id="ubSegBr-tbl" class="me-bl-tblhost"></div>'+
    '<div class="acx-cap me-bl-note" id="ubSegBrCap"></div></div>';
}
function sBridgeSync(pane){
  var mb=pane.querySelector('.sbr-mode .active'), mode=mb?mb.getAttribute('data-sbrm'):'seg';
  aShow(pane.querySelector('.sbr-ctl-seg'), mode==='seg'); aShow(pane.querySelector('.sbr-ctl-cost'), mode==='cost');
  var g=pane.querySelector('.sbr-gran .active'), q=!!(g&&g.getAttribute('data-sbrg')==='q');
  aShow(pane.querySelector('.sbr-cy'), !q); aShow(pane.querySelector('.sbr-cq'), q);
}
function sBuildBridge(){
  var pane=sPane(); if(!pane) return;
  var mb=pane.querySelector('.sbr-mode .active'), mode=mb?mb.getAttribute('data-sbrm'):'seg', cap=pane.querySelector('#ubSegBrCap'), steps;
  function A(sel,attr){ var b=pane.querySelector(sel+' .active'); return b?b.getAttribute(attr):null; }
  function fy(y){ return fyLab(y)+(y>S_YA[S_LA]?'E':''); }
  if(mode==='seg'){
    var y0=+A('.sbr-from','data-sbrf'), y1=+A('.sbr-to','data-sbrt');
    if(!(y1>y0)){ aDestroy('ubSegBr'); var tw=$id('ubSegBr-tbl'); if(tw) tw.innerHTML=''; if(cap) cap.innerHTML='Pick a “to” year after the “from” year.'; return; }
    var v0=SEG_DEF.map(function(s){ return sOiY(y0,s); }), v1=SEG_DEF.map(function(s){ return sOiY(y1,s); });
    if(v0.concat(v1).some(function(v){ return v==null; })){ aDestroy('ubSegBr'); if(cap) cap.innerHTML='No segment operating income for one of the two years.'; return; }
    var t0=v0.reduce(function(a,v){ return a+v; },0)/1000, run=t0;
    steps=[{label:fy(y0)+' Non-GAAP OI', kind:'base', color:INK, range:[0,run], runAfter:run, val:run}];
    var parts=SEG_DEF.map(function(s,i){ var d=(v1[i]-v0[i])/1000, lo=run; run=lo+d;
      steps.push({label:s.k==='corp'?'Corporate & Platform R&D':s.lab, kind:d>=0?'up':'down', color:s.c, dc:d>=0?POS:NEG, range:[Math.min(lo,run),Math.max(lo,run)], runAfter:run, val:d}); return d; });
    steps.push({label:fy(y1)+' Non-GAAP OI', kind:'total', color:POS, range:[0,run], runAfter:null, val:run});
    aBuildBrWaterfall('ubSegBr', steps, BR_FMT_D);
    if(cap) cap.innerHTML='Non-GAAP operating income went from <b>'+sB(t0*1000)+'</b> in '+fy(y0)+' to <b>'+sB(run*1000)+'</b> in '+fy(y1)+': '+
      SEG_DEF.map(function(s,i){ return esc(s.lab)+' '+(parts[i]>=0?'added':'took')+' <b>'+sB(Math.abs(parts[i])*1000)+'</b>'; }).join(', ')+
      '. Segment Operating Income basis (recast from 1Q24). Source: '+esc(UBER_SEG_SRC)+(y1>S_YA[S_LA]?'; '+fy(y1)+' = Bloomberg consensus segment operating income (as of '+esc(uberBBG.asOf)+')':'')+'.';
    return;
  }
  var k=A('.sbr-seg','data-sbrs')||'mob', s=sSeg(k), gq=A('.sbr-gran','data-sbrg')==='q', a, b, la, lb, basis;
  if(gq){ var qp=A('.sbr-cq','data-sbrq')||SBR_QS[SBR_QS.length-1].p, iq=UBER_SEG_SOI_Q.map(function(r){ return r.p; }).indexOf(qp);
    b=UBER_SEG_SOI_Q[iq][k]; a=UBER_SEG_SOI_Q[iq-4][k]; lb=UBER_SEG_SOI_Q[iq].p; la=UBER_SEG_SOI_Q[iq-4].p; basis='segment operating income'; }
  else { var c0=+A('.sbr-cfrom','data-sbrcf'), c1=+A('.sbr-cto','data-sbrct');
    if(!(c1>c0)){ aDestroy('ubSegBr'); var tw2=$id('ubSegBr-tbl'); if(tw2) tw2.innerHTML=''; if(cap) cap.innerHTML='Pick a “to” year after the “from” year.'; return; }
    a=UBER_SEG_EBITDA_Y[c0][k]; b=UBER_SEG_EBITDA_Y[c1][k]; la=fyLab(c0); lb=fyLab(c1); basis='segment Adjusted EBITDA'; }
  var short=gq?'SOI':'Adj. EBITDA', r0=a.oi/1000, run2=r0;
  steps=[{label:la+' '+short, kind:'base', color:r0>=0?INK:NEG, range:[Math.min(0,run2),Math.max(0,run2)], runAfter:run2, val:r0}];
  function st2(lab, d){ var lo=run2; run2=lo+d; steps.push({label:lab, kind:d>=0?'up':'down', color:d>=0?POS:NEG, range:[Math.min(lo,run2),Math.max(lo,run2)], runAfter:run2, val:d}); }
  st2('Revenue', (b.rev-a.rev)/1000); st2('Platform-participant costs', -(b.pp-a.pp)/1000); st2('Other costs', -(b.other-a.other)/1000);
  steps.push({label:lb+' '+short, kind:'total', color:b.oi>=0?POS:NEG, range:[Math.min(0,run2),Math.max(0,run2)], runAfter:null, val:run2});
  aBuildBrWaterfall('ubSegBr', steps, BR_FMT_D);
  if(cap){ var mA=a.rev?a.oi/a.rev*100:null, mB=b.rev?b.oi/b.rev*100:null;
    cap.innerHTML='<b>'+esc(s.lab)+'</b>, '+la+' → '+lb+' ('+basis+'): revenue '+(b.rev>=a.rev?'added':'took')+' <b>'+sB(Math.abs(b.rev-a.rev))+'</b>, Platform Participant direct transaction costs '+(b.pp>=a.pp?'took':'gave back')+' <b>'+sB(Math.abs(b.pp-a.pp))+'</b> and other costs '+(b.other>=a.other?'took':'gave back')+' <b>'+sB(Math.abs(b.other-a.other))+'</b> — margin on revenue '+sPct(mA)+' → '+sPct(mB)+'.'+
      (gq?' Each quarter is compared with the same quarter a year earlier; the 4Q25 release gives no cost split, so 4Q25 is not offered.':' Years use Segment Adjusted EBITDA, the measure the 10-K reports with this split.')+
      (k==='mob'&&gq&&(lb==='1Q26'||lb==='2Q26')?' The UK business-model change lowers revenue and platform-participant costs by the same amount, so both bars shrink without touching profit.':'')+' Source: '+esc(UBER_SEG_SRC)+'.'; }
}

// ── 4 · Segment deep dives (collapsible) — one tab per segment, same formal layout as the Expense lines ──
function sSpark(vals, labs, fmt){ var mx=Math.max.apply(null,vals.map(function(v){ return Math.abs(v||0); }))||1;
  return '<div class="ew-spark">'+vals.map(function(v,i){ return '<div class="ew-sb'+(i===vals.length-1?' on':'')+'"><div class="ew-sb-v">'+fmt(v)+'</div><div class="ew-sb-bar" style="height:'+Math.max(2,Math.round(Math.abs(v||0)/mx*72))+'px"></div><div class="ew-sb-l">'+labs[i]+'</div></div>'; }).join('')+'</div>'; }
function sCostTable(k){
  var rows=SEG_YRS.map(function(y){ return [fyLab(y), 'Adj. EBITDA', UBER_SEG_EBITDA_Y[y][k]]; });
  UBER_SEG_SOI_Q.filter(function(r){ return r[k].pp!=null; }).slice(-2).forEach(function(r){ rows.push([r.p, 'Op. income', r[k]]); });
  return '<div class="twrap ew-twrap"><table class="rt ew-tbl"><thead><tr><th>Period</th><th>Measure</th><th>Revenue</th><th>Platform-participant costs</th><th>Other costs</th><th>Segment profit</th><th>Margin on revenue</th></tr></thead><tbody>'+
    rows.map(function(r){ var d=r[2], m=d.rev?d.oi/d.rev:null;
      return '<tr><td class="ew-tk">'+r[0]+'</td><td>'+r[1]+'</td><td>'+sB(d.rev)+'</td><td>'+sB(d.pp)+'</td><td>'+sB(d.other)+'</td><td>'+sB(d.oi)+'</td><td>'+(m==null?'—':sPct(m*100))+'</td></tr>'; }).join('')+
    '</tbody></table></div>';
}
function sDive(d){
  var k=d.k, s=sSeg(k), yL=SEG_YRS[SEG_YRS.length-1], ey=UBER_SEG_EBITDA_Y[yL];
  var rev=ey[k].rev, eb=ey[k].oi, totRev=UBER_OPEX[yL]?UBER_OPEX[yL].revenue:null, gbY=ry(s.gk,'act',yL), freight=k==='fr';
  var sq=UBER_SEG_SOI_Q, qL=sq[sq.length-1], qP=sq[sq.length-5];
  var gq=rq(s.gk,'act',qL.p), gp=rq(s.gk,'act',qP.p);
  function mg(v, r, g){ return freight?(r?v/r*100:null):(g?v/g*100:null); }
  var base=freight?'of revenue':'of Gross Bookings';
  var kp=[[sB(rev), fyLab(yL)+' revenue · '+sPct(totRev?rev/totRev*100:null)+' of Uber'],
    [sB(eb), fyLab(yL)+' segment Adjusted EBITDA · '+sPct(mg(eb,rev,gbY))+' '+base],
    [sB(qL[k].oi), qL.p+' segment operating income · '+sPct(mg(qL[k].oi,qL[k].rev,gq))+' '+base+' ('+sPct(mg(qP[k].oi,qP[k].rev,gp))+' in '+qP.p+')'],
    [sPct(ey[k].pp/(ey[k].pp+ey[k].other)*100), 'of '+fyLab(yL)+' segment costs are Platform Participant direct transaction costs']];
  var h='<div class="ew-h">Key figures</div><div class="ov-kpis">'+kp.map(function(x){ return '<div class="ov-kpi"><div class="ov-kpi-v">'+x[0]+'</div><div class="ov-kpi-d muted">'+x[1]+'</div></div>'; }).join('')+'</div>';
  h+='<div class="ew-h">Definition — Form 10-K</div><div class="ew-q ew-def">“'+d.def+'”<span class="ew-att">— Uber Form 10-K for FY'+yL+', Note 13</span></div>';
  h+='<div class="ew-h">The business</div><div class="ew-note">'+d.business+'</div>';
  var qs=sq.map(function(r){ return r.p; }), mv=sq.map(function(r){ return mg(r[k].oi, r[k].rev, rq(s.gk,'act',r.p)); });
  h+='<div class="ew-h">Segment operating income, % '+(freight?'of revenue':'of Gross Bookings')+', '+qs[0]+'–'+qs[qs.length-1]+'</div>'+
    sSpark(mv, qs, function(v){ return v==null?'—':v.toFixed(1)+'%'; });
  h+='<div class="ew-h">Cost split — what Uber breaks out by segment</div>'+sCostTable(k);
  h+='<div class="ew-note ew-small">Platform Participant direct transaction costs: “'+esc(UBER_SEG_TXT.pp)+'” Other: “'+esc(UBER_SEG_TXT.other)+'” (Form 10-Q 2Q26, segment note; under Segment Adjusted EBITDA “other” excluded stock-based compensation and D&amp;A.)</div>';
  h+='<div class="ew-h">What drives it</div><div class="twrap ew-twrap"><table class="rt ew-tbl"><tbody>'+d.moves.map(function(m){ return '<tr><td class="ew-tk">'+m[0]+'</td><td>'+m[1]+'</td></tr>'; }).join('')+'</tbody></table></div>';
  h+='<div class="ew-h">What the segment note discloses — and what it does not</div><div class="twrap ew-twrap"><table class="rt ew-tbl"><tbody>'+
    ewTableRows('Disclosed by segment', [['','Revenue, segment profit','Revenue and segment profit (Adjusted EBITDA through 4Q25, operating income from 1Q26, recast to 1Q24), annual and quarterly; the two-way cost split; Gross Bookings in the earnings release.']])+
    ewTableRows('Not disclosed by segment', [['','Assets, capex, D&amp;A','“'+esc(UBER_SEG_TXT.codm)+'”'],
      ['','Income-statement lines','No cost of revenue, operations and support, sales and marketing, R&amp;D or G&amp;A by segment — only the two-way split.']])+
    ewTableRows('What is not allocated', [['','Corporate G&amp;A and Platform R&amp;D','“'+esc(UBER_SEG_TXT.corp)+'”']])+
    '</tbody></table></div>';
  h+=ewCallsTable(d.calls);
  h+='<div class="ov-foot">Sources: '+esc(UBER_SEG_SRC)+'; Gross Bookings from the Results dataset (earnings releases); MD&amp;A drivers from the Form 10-K FY2025 and the Form 10-Q 2Q26; earnings-call transcripts in docs/calls.</div>';
  return h;
}
function sDivesBody(){
  var yL=SEG_YRS[SEG_YRS.length-1];
  var tabs=UBER_SEG_DIVES.map(function(d,i){ var s=sSeg(d.k), e=UBER_SEG_EBITDA_Y[yL][d.k];
    return '<button type="button" class="exp-tab'+(i===0?' active':'')+'" data-segtab="'+d.k+'"><span class="exp-dot" style="background:'+s.c+'"></span>'+esc(d.name)+' <span class="exp-tag">'+sB(e.oi)+' Adj. EBITDA · '+fyLab(yL)+'</span></button>'; }).join('');
  return '<div class="exp-explorer exp-flat"><div class="exp-tabs">'+tabs+'</div><div class="exp-panels">'+
    UBER_SEG_DIVES.map(function(d,i){ return '<div class="exp-panel exp-panel-card" data-segpanel="'+d.k+'"'+(i>0?' hidden':'')+'>'+sDive(d)+'</div>'; }).join('')+'</div></div>';
}
function uberBlFootSegments(){
  var e0=UBER_SEG_EBITDA_Q[0].p, e1=UBER_SEG_EBITDA_Q[UBER_SEG_EBITDA_Q.length-1].p, o0=UBER_SEG_SOI_Q[0].p, o1=UBER_SEG_SOI_Q[UBER_SEG_SOI_Q.length-1].p;
  return '<div class="ov-foot">Sources — '+esc(UBER_SEG_SRC)+': Segment Adjusted EBITDA '+fyLab(SEG_YRS[0])+'–'+fyLab(SEG_YRS[SEG_YRS.length-1])+' and '+esc(e0)+'–'+esc(e1)+' (a Q4 is the year less the nine months), Segment Operating Income '+esc(o0)+'–'+esc(o1)+', with the cost split where the filing gives it; '+
    'Results dataset for segment revenue and Gross Bookings and for the quarterly Summit and consensus series; Summit DCF model, frozen on purpose (not live) — snapshot '+esc(UBER_SUMMIT.snapshot)+', segment operating income and revenue by year; '+
    'Bloomberg consensus export (BBG_CONSENSUS, as of '+esc(uberBBG.asOf)+') for segment Gross Bookings, revenue and operating income forward; earnings-call transcripts in docs/calls. Forward figures are estimates.</div>';
}
function sBuildSegments(){
  var pane=sPane(); if(!pane) return;
  aWireCollaps(pane);
  sBuildProfit(); sBuildMix(); sBridgeSync(pane); sBuildBridge();
  if(pane._segWired) return; pane._segWired=true;
  var tog=function(sel,after){ pane.querySelectorAll(sel+' button').forEach(function(b){ b.onclick=function(){ pane.querySelectorAll(sel+' button').forEach(function(x){ x.classList.toggle('active',x===b); }); after(); }; }); };
  ['.sbr-mode','.sbr-gran'].forEach(function(s){ tog(s, function(){ sBridgeSync(pane); sBuildBridge(); }); });
  ['.sbr-from','.sbr-to','.sbr-seg','.sbr-cfrom','.sbr-cto','.sbr-cq'].forEach(function(s){ tog(s, sBuildBridge); });
  var stabs=pane.querySelectorAll('.exp-tab[data-segtab]');
  stabs.forEach(function(b){ b.onclick=function(){ var key=b.getAttribute('data-segtab');
    stabs.forEach(function(x){ x.classList.toggle('active',x===b); });
    pane.querySelectorAll('.exp-panel[data-segpanel]').forEach(function(p){ p.hidden=(p.getAttribute('data-segpanel')!==key); }); }; });
}
// Mount: '<div class="ovt-subpane" data-ovst="segments">'+uberBlSegmentsHtml()+'</div>' in the Bottom Line pane;
// build lazily once visible: uberBlSegmentsBuild(root).
export function uberBlSegmentsHtml(){
  return '<div class="seg-gsec" data-sgsec="oimargin">'+sProfitBody()+'</div>'+
    '<div class="seg-gsec me-bl-gap" data-sgsec="mix">'+sMixBody()+'</div>'+
    '<div class="seg-gsec me-bl-gap" data-sgsec="bridge">'+sBridgeBody()+'</div>'+
    aCollap('Segment deep dives — Mobility, Delivery and Freight (key figures, cost split, drivers, what is disclosed, calls)', sDivesBody(), false)+uberBlFootSegments();
}
export function uberBlSegmentsBuild(root){ if(root) _root=root; sBuildSegments(); }
